function paintTurnPerimeter(){
 const now=Date.now()+(local?0:serverOffset),remaining=Math.max(0,(game.turnDeadline||now)-now);
 document.querySelectorAll('#scores .player-card').forEach(card=>{
  const active=Number(card.dataset.seat)===game.turn&&!!game.turnSeconds&&!game.over;
  let ring=card.querySelector('.turn-progress');
  if(active&&!ring){ring=document.createElementNS('http://www.w3.org/2000/svg','svg');ring.setAttribute('viewBox','0 0 100 100');ring.setAttribute('preserveAspectRatio','none');ring.setAttribute('aria-hidden','true');ring.classList.add('turn-progress');ring.innerHTML='<path d="M50 2 H86 Q98 2 98 14 V86 Q98 98 86 98 H14 Q2 98 2 86 V14 Q2 2 14 2 Z" pathLength="1"/>';card.append(ring)}
  if(ring){ring.classList.toggle('hidden',!active);ring.style.setProperty('--turn-fraction',String(Math.min(1,remaining/((game.turnSeconds*1000+(game.timeSupportUsed?.[game.turn]===(game.turnSerial||0)?30000:0))||1))));ring.classList.toggle('urgent',remaining<=10000)}
 });
}
