let friendSequence=0,friendMutation=0,friendWrites=0,friendQueue=Promise.resolve();
async function friendsApi(action='',extra={}){
 if(!action&&friendWrites)return;const owner=accounts.profile?.id;
 const execute=async()=>{const seq=++friendSequence,version=friendMutation,token=await accounts.accountToken(),v=await api('friends'+action,{accountToken:token,...extra},20000);if(accounts.profile?.id!==owner||seq!==friendSequence||version!==friendMutation)return v;friendsData=v;friendsOwner=owner;save('renkio-friends:'+owner,v);renderFriends();return v};
 if(!action)return execute();friendMutation++;friendWrites++;
 const job=friendQueue.catch(()=>{}).then(execute);friendQueue=job;
 try{return await job}finally{friendWrites--;if(!friendWrites)refreshFriends().catch(()=>{})}
}
