function renderStats(){const matches=competitiveMatches(archived(),accounts.profile?.id),results=matches.map(m=>matchOutcome(m,accounts.profile?.id)),scores=matches.map(m=>m.players.find(p=>p.id===accounts.profile?.id)?.score||0);$('statsGrid').replaceChildren();for(const [label,value]of [['Maç',matches.length],['Galibiyet',results.filter(v=>v==='win').length],['Mağlubiyet',results.filter(v=>v==='loss').length],['Beraberlik',results.filter(v=>v==='draw').length],['En yüksek puan',Math.max(0,...scores)],['Toplam puan',scores.reduce((a,b)=>a+b,0)]]){const n=node('div','stat-card');n.append(node('b','',String(value)),node('span','',label));$('statsGrid').append(n)}const list=$('allMatches');list.replaceChildren();for(const m of matches){const n=node('button','saved-match'),own=m.players.find(p=>p.id===accounts.profile?.id),rivals=m.players.filter(p=>p!==own);n.dataset.outcome=matchOutcome(m,accounts.profile.id);const label=node('span','',rivals.map(p=>p.name).join(', '));label.append(node('small','',new Date(m.at).toLocaleDateString(locale())));n.append(label,node('strong','',m.players.map(p=>p.score).join(' : ')));n.onclick=()=>openMatch(m);list.append(n)}if(!matches.length)list.append(node('p','empty-state','İlk maçından sonra burada görüşelim.'))}
