function addGiftControls(dialog,id){
 const area=node('details','profile-gifts'),title=node('summary');title.innerHTML=icon('gift');title.append(node('span','','Hediye gönder'));area.append(title);
 const form=node('form','gift-form'),select=document.createElement('select');select.setAttribute('aria-label',t('Hediye'));
 for(const [value,label]of [['joker','Joker'],['hint','İpucu'],...(accounts.profile?.id==='415148343475'?[['diamonds','Elmas']]:[])]){const option=node('option','',t(label));option.value=value;select.append(option)}
 const amount=document.createElement('input');amount.type='number';amount.min='1';amount.max='1000000';amount.value='1';amount.setAttribute('aria-label',t('Adet'));const send=node('button','button button-purple','Gönder');send.type='submit';const status=node('small','gift-status');status.setAttribute('role','status');form.append(select,amount,send);area.append(form,status);dialog.append(area);
 form.onsubmit=async e=>{e.preventDefault();if(form.dataset.sending==='yes')return;form.dataset.sending='yes';send.disabled=true;status.textContent='';const signature=select.value+':'+amount.value;if(form.dataset.signature!==signature){form.dataset.signature=signature;form.dataset.receipt=crypto.randomUUID()}const receipt=form.dataset.receipt;try{wallet=await api('gifts',{accountToken:await accounts.accountToken(),playerId:id,item:select.value,amount:Number(amount.value),receipt},20000);paintReward();dialog.close();dialog.remove();toast('Hediye gönderildi.','success')}catch(error){status.textContent=t(error.message);form.dataset.sending='no';send.disabled=false}};
}

let directPeer=null,directRequest=0,directRows=[],directPolling=false;const directReceipts=new Map();
function drawDirect(){const host=$('directMessages'),bottom=host.scrollHeight-host.scrollTop-host.clientHeight<60;host.replaceChildren();for(const m of directRows){const row=node('div','direct-message'+(m.from===accounts.profile?.id?' own':''));row.append(node('span','',m.text),node('small','',new Date(m.at).toLocaleTimeString(locale(),{hour:'2-digit',minute:'2-digit'})));if(m.from!==accounts.profile?.id){row.tabIndex=0;row.setAttribute('role','button');row.onclick=()=>openMessageActions({...m,name:$('directName').textContent,direct:true});row.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();row.click()}}}host.append(row)}if(bottom)host.scrollTop=host.scrollHeight;$('olderDirect').classList.toggle('hidden',directRows.length<100)}
async function openMessages(){directPeer=null;directRequest++;$('directConversation').classList.add('hidden');$('conversationList').classList.remove('hidden');const request=directRequest;try{await accounts.ensureAccount();const v=await api('messages/list',{accountToken:await accounts.accountToken()});if(request!==directRequest)return;const host=$('conversationList');host.replaceChildren();for(const c of v.conversations){const b=node('button','menu-link');b.append(playerAvatar(c.name,0,'',false,c.avatar,c.playerId),node('span','',c.name),node('small','',c.last.text));b.onclick=()=>openDirect(c.playerId);host.append(b)}if(!v.conversations.length)host.append(node('p','empty-state',t('Henüz mesaj yok.')))}catch(e){if(request===directRequest)$('conversationList').textContent=t(e.message)}}
async function openDirect(id){if(view!=='home')await goHome();showHub('messages',true);directPeer=id;const request=++directRequest;directRows=[];$('conversationList').classList.add('hidden');$('directConversation').classList.remove('hidden');$('directMessages').replaceChildren();$('directInput').value='';$('directStatus').textContent='';try{const v=await api('messages',{accountToken:await accounts.accountToken(),playerId:id});if(request!==directRequest)return;$('directName').textContent=v.name;directRows=v.messages;drawDirect()}catch(e){if(request===directRequest)$('directStatus').textContent=t(e.message)}}
$('backConversations').onclick=openMessages;
$('olderDirect').onclick=async()=>{const id=directPeer,request=directRequest;if(!id||!directRows.length)return;try{const v=await api('messages',{accountToken:await accounts.accountToken(),playerId:id,before:directRows[0].at,beforeId:directRows[0].id});if(request!==directRequest)return;directRows=[...v.messages,...directRows];drawDirect();if(v.messages.length<100)$('olderDirect').classList.add('hidden')}catch(e){$('directStatus').textContent=t(e.message)}};
$('directComposer').onsubmit=async e=>{e.preventDefault();const input=$('directInput'),text=input.value.trim(),id=directPeer,request=directRequest;if(!text||!id||directPolling)return;directPolling=true;const button=e.currentTarget.querySelector('button');button.disabled=true;try{const signature=id+':'+text;let receipt=directReceipts.get(signature);if(!receipt){receipt=crypto.randomUUID();directReceipts.set(signature,receipt)}const v=await api('messages/send',{accountToken:await accounts.accountToken(),playerId:id,text,receipt});directReceipts.delete(signature);if(request!==directRequest)return;input.value='';directRows=v.messages;drawDirect();$('directMessages').scrollTop=$('directMessages').scrollHeight;sound.play('message')}catch(error){if(request===directRequest)$('directStatus').textContent=t(error.message)}finally{directPolling=false;button.disabled=false}};
setInterval(async()=>{if(document.hidden||document.body.dataset.page!=='messages'||!directPeer||directPolling)return;const id=directPeer,request=directRequest;directPolling=true;try{const v=await api('messages',{accountToken:await accounts.accountToken(),playerId:id});if(request===directRequest){const old=new Set(directRows.map(m=>m.id));if(v.messages.some(m=>!old.has(m.id))){directRows=[...directRows.filter(m=>!v.messages.some(n=>n.id===m.id)),...v.messages];drawDirect()}}}catch{}finally{directPolling=false}},3000);

// Existing Android shells can also check and activate safely once per launch.
if(window.RenkioNative?.refresh&&!sessionStorage.getItem('renkio-auto-update-checked')){sessionStorage.setItem('renkio-auto-update-checked','1');setTimeout(()=>{if(view==='home')window.RenkioNative.refresh()},1000)}
if(window.RenkioNative?.enableNotifications&&!nativePushState()?.asked&&!read('renkio-notification-asked')&&preferences.alerts){save('renkio-notification-asked',true);window.RenkioNative.enableNotifications()}

function lastOnline(at){if(!at)return t('Son görülme bilgisi yok');const seconds=Math.max(0,(Date.now()-at)/1000);if(seconds<45)return t('Çevrim içi');if(seconds<60)return t('Az önce');const [value,unit]=seconds<3600?[Math.floor(seconds/60),'minute']:seconds<86400?[Math.floor(seconds/3600),'hour']:[Math.floor(seconds/86400),'day'];return t('Son görülme')+': '+new Intl.RelativeTimeFormat(locale(),{numeric:'always'}).format(-value,unit)}
let activityBusy=false;const giftAcks=new Set();
async function pollActivity(){if(activityBusy||document.hidden||!navigator.onLine||!accounts.profile)return;activityBusy=true;const owner=accounts.profile.id;try{const value=await api('activity',{accountToken:await accounts.accountToken(),ack:[...giftAcks],friends:document.body.dataset.page==='friends'||$('friendsDialog').open},20000);if(accounts.profile?.id!==owner)return;giftAcks.clear();if(value.friends){friendsData=value.friends;renderFriends()}for(const gift of value.gifts){const key='renkio-gift:'+owner+':'+gift.id;if(!read(key)){save(key,true);toast(gift.name+' · '+gift.amount+' '+t({joker:'Joker',hint:'İpucu',diamonds:'Elmas'}[gift.item])+' · '+t('Hediye aldın'),'success');if(preferences.alerts)sound.play('message')}giftAcks.add(gift.id)}if(value.gifts.length)await refreshWallet()}catch{}finally{activityBusy=false}}
setInterval(pollActivity,8000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)pollActivity()});window.addEventListener('online',pollActivity);setTimeout(pollActivity,1500);
